	t.Code = record.Code
	t.Wip_cost_account = record.Wip_cost_account
	t.Wip_sales_account = record.Wip_sales_account
	t.Cost_account = record.Cost_account
	t.Sales_account = record.Sales_account
	t.G_l_exp_sales_acc = record.G_l_exp_sales_acc
